describe('Comment on Record', () => {
  beforeEach(() => {
    cy.visit('/records');
  });

  it('should successfully submit a comment on a record', () => {
    // Verify the list of records is displayed
    cy.get('[data-testid="record-list"]').should('be.visible');
    cy.get('[data-testid="record-item"]').should('have.length.greaterThan', 0);

    // Navigate to a specific record
    cy.get('[data-testid="record-item"]').first().click();
    cy.get('[data-testid="record-details"]').should('be.visible');

    // Verify comment form is visible
    cy.get('[data-testid="comment-form"]').should('be.visible');

    // Fill in the comment form
    cy.get('[data-testid="comment-input"]').type('This is a great product!');
    cy.get('[data-testid="comment-submit-button"]').click();

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Comment submitted successfully');

    // Verify record details remain unchanged
    cy.get('[data-testid="record-details"]').should('contain', 'This is a great product!');

    // Verify comment is visible in the list
    cy.get('[data-testid="record-item"]').first().should('contain', 'This is a great product!');
  });

  it('should display error when comment submission fails', () => {
    // Navigate to a record
    cy.get('[data-testid="record-item"]').first().click();
    cy.get('[data-testid="record-details"]').should('be.visible');

    // Fill in the comment form
    cy.get('[data-testid="comment-input"]').type('This is a great product!');

    // Submit empty comment
    cy.get('[data-testid="comment-submit-button"]').click();

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Comment cannot be empty');

    // Verify record details remain unchanged
    cy.get('[data-testid="record-details"]').should('contain', 'This is a great product!');

    // Verify comment form is still visible
    cy.get('[data-testid="comment-form"]').should('be.visible');
  });
});
